#!/usr/bin/env node
// Execute the exact two private frozen TS policy functions, extracted by AST
// into an isolated VM. No handwritten replica; not a product-entry claim.
import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import vm from 'node:vm';import {spawnSync} from 'node:child_process';import {createHash} from 'node:crypto';import {pathToFileURL,fileURLToPath} from 'node:url';
const baseline=process.env.PDRS_BASELINE??'/Users/da/ws/pilotdeck-rs/resources/PilotDeck',out=path.resolve(process.argv[2]);fs.mkdirSync(out);assert.equal(process.version,'v22.22.0');const revision='cc7c4e653b15c8b2cec7bcf2d15d41d69396ae85';assert.equal(spawnSync('git',['-C',baseline,'rev-parse','HEAD'],{encoding:'utf8'}).stdout.trim(),revision);assert.equal(spawnSync('git',['-C',baseline,'diff','--quiet','HEAD','--','src','packages']).status,0);
const source=path.join(baseline,'src/cli/ProjectSessionRuntimeBundle.ts'),built=path.join(baseline,'dist/src/cli/ProjectSessionRuntimeBundle.js');const sha=bytes=>createHash('sha256').update(bytes).digest('hex');const {default:ts}=await import(pathToFileURL(path.join(baseline,'node_modules/typescript/lib/typescript.js')));const sourceText=fs.readFileSync(source,'utf8');const config=JSON.parse(fs.readFileSync(path.join(baseline,'tsconfig.json'),'utf8'));const compiler=ts.convertCompilerOptionsFromJson(config.compilerOptions,baseline).options;assert.equal(ts.transpileModule(sourceText,{fileName:source,compilerOptions:{...compiler,module:ts.ModuleKind.ESNext}}).outputText,fs.readFileSync(built,'utf8'));
const ast=ts.createSourceFile(source,sourceText,ts.ScriptTarget.Latest,true);const functions=['blockedToolNames','matchesToolSelector'].map(name=>{const nodes=ast.statements.filter(node=>ts.isFunctionDeclaration(node)&&node.name?.text===name);assert.equal(nodes.length,1);const node=nodes[0];return{name,text:node.getText(ast),startLine:ast.getLineAndCharacterOfPosition(node.getStart(ast)).line+1};});
const compiled=ts.transpileModule(functions.map(fn=>fn.text).join('\n'),{compilerOptions:{target:ts.ScriptTarget.ES2022}}).outputText;const blocked=vm.runInNewContext(compiled+'\nblockedToolNames;',{}, {timeout:1000});
for(const key of Object.keys(process.env))delete process.env[key];Object.assign(process.env,{HOME:path.join(out,'home'),PILOT_HOME:path.join(out,'pilot'),PATH:''});fs.mkdirSync(process.env.HOME);fs.mkdirSync(process.env.PILOT_HOME);
const policies=[null,{}, {process:'deny'},{filesystem:'deny'},{filesystem:'read_only'},{network:'deny'},{process:'deny',filesystem:'read_only'},{process:'deny',filesystem:'deny'},{network:'deny',filesystem:'read_only'},{network:'deny',filesystem:'deny'},{process:'deny',network:'deny'},{type:'tool_policy',process:'deny',filesystem:'deny',network:'deny'}];
const names=['read_file','write_file','edit_file','edit_notebook','bash','execute_code','agent','task_run','task_','task','TASK_run','task/run','subagent','send_message','web_fetch','request_user_input','custom_probe','Write','write_file\ud800'];
const kinds=[undefined,'filesystem','shell','mcp','custom','network','memory','subagent','SHELL',''];
const records=[];
for(const sandbox of policies)for(const name of names)for(const kind of kinds){const tool={name,...(kind===undefined?{}:{kind})};const actual=blocked({sandbox,explicit:{},tools:[tool]});records.push({sandbox,tool,allowed:!actual.has(name)});}
// Other policies compose by union; sandbox never restores an explicitly denied
// tool or broadens allowedTools. These rows are reference-only for host wiring.
const unions=[{sandbox:{process:'deny'},explicit:{allowedTools:['read_file','bash']},tools:[{name:'read_file',kind:'filesystem'},{name:'bash',kind:'shell'},{name:'web_fetch',kind:'network'}]},{sandbox:{filesystem:'read_only'},managed:{deny:['read_*']},explicit:{},tools:[{name:'read_file',kind:'filesystem'},{name:'custom_probe',kind:'filesystem'},{name:'write_file',kind:'memory'}]}].map(input=>({input,blocked:[...blocked(input)]}));
fs.writeFileSync(path.join(out,'oracle.json'),JSON.stringify({boundary:'exact fixed TS private function source in isolated VM; no RuntimeBundle or Gateway execution claim',records,unions},null,2)+'\n');fs.writeFileSync(path.join(out,'identity.json'),JSON.stringify({revision,node:process.version,sourceSha256:sha(fs.readFileSync(source)),distSha256:sha(fs.readFileSync(built)),driverSha256:sha(fs.readFileSync(fileURLToPath(import.meta.url))),functions:functions.map(({name,text,startLine})=>({name,startLine,sha256:sha(text)}))},null,2)+'\n');console.log(JSON.stringify({records:records.length,unions:unions.length,sha256:sha(fs.readFileSync(path.join(out,'oracle.json')))}));
